                    ["translations"] = {
                        ["EN"] = {
                            "Just doing what had to be done.",
                            "Anyone else would have done the same.",
                            "Just doing my part to keep us alive.",
                            "Glad I could pull it off.",
                            "It was what the situation called for.",
                            "No big deal. Just handling business.",
                            "Happy to help. We are in this together.",
                            "Just glad it worked out in the end.",
                            "I did what I could. Thanks for noticing.",
                            "All part of surviving another day.",
                        },
                        ["TL"] = {
                            "Ginawa ko lang kung ano ang kailangang gawin.",
                            "Kahit sino gagawin din ang ganoon.",
                            "Tungkulin ko lang para mapanatili tayong buhay.",
                            "Mabuti at nagawa ko nang maayos.",
                            "Iyon ang hiningi ng sitwasyon.",
                            "Wala 'yon. Ginagawa lang ang trabaho.",
                            "Masayang tumulong. Magkasama tayo rito.",
                            "Mabuti na lang at naging maayos ang kinahinatnan.",
                            "Ginawa ko ang kaya ko. Salamat sa pagpansin.",
                            "Parte lang 'yan ng pagsisikap na mabuhay pa ng isang araw.",
                        },
                    },
                    ["variantID"] = "neutral",
                },
                {
                    ["fallback"] = "Good. I was hoping you noticed.",
                    ["realizationKey"] = "2",
                    ["role"] = "spoken_action",
                    ["templateID"] = "convo.tool_reply.praise.say.2.neutral",
                    ["translations"] = {
                        ["EN"] = {
                            "Good. I was hoping you noticed.",
                            "Glad to know the effort did not go overlooked.",
                            "It feels good to have that acknowledged.",
                            "I put sweat into that. Glad you caught it.",
                            "Thanks. It means a lot that you saw the work.",
                            "Nice to have your approval on that.",
                            "I wanted to make sure it was done right.",
                            "Thanks. Recognition goes a long way.",
                            "Glad my efforts are paying off for us.",
                            "Good to hear. I will keep at it.",
                        },
                        ["TL"] = {
                            "Mabuti. Umasa nga akong mapapansin mo.",
                            "Mabuti at hindi nawalang-bisa ang pagod ko.",
                            "Masarap sa pakiramdam na kinikilala 'yon.",
                            "Pinagpawisan ko 'yon. Mabuti at nakita mo.",
                            "Salamat. Malaking bagay na nakita mo ang pinaghirapan ko.",
