                    ["translations"] = {
                        ["EN"] = {
                            "That is nice to hear from you.",
                            "Thank you. Coming from you, that carries weight.",
                            "I respect your opinion, so thanks.",
                            "That gives me a solid boost. Thank you.",
                            "I appreciate hearing that today.",
                            "Always good to know where I stand with you.",
                            "Thanks. That takes some of the strain off.",
                            "I am grateful for the praise.",
                            "Thank you. It is encouraging.",
                            "Much appreciated. Let us keep winning.",
                        },
                        ["TL"] = {
                            "Masarap marinig 'yan galing sa 'yo.",
                            "Salamat. Dahil galing sa 'yo, may bigat 'yan.",
                            "Iginagalang ko ang opinyon mo, kaya salamat.",
